<?php

function gcd($a, $b) {
    if ($a > $b) {
        $tmp = $a;
        $a = $b;
        $b = $tmp;
    }

    // Special case for zero
    if ($a == 0 || $b == 0) {
        return $a + $b;
    }

    // Calculate GCD using Euclidean algorithm
    $result = 1;

    while (true) {
        $remain = $b % $a;

        if ($remain == 0) {
            $result *= $a;
            break;
        } else {
            $b = $a;
            $a = $remain;
        }
    }
    return $result;
}

$parts = explode(' ', trim(fgets(STDIN)));
$simon = (int)$parts[0];
$antisimon = (int)$parts[1];
$stones = (int)$parts[2];

while (true) {
    // Simon plays
    $simonQuota = gcd($simon, $stones);

    if ($simonQuota <= $stones) {
        $stones -= $simonQuota;
    } else {
        echo "1\n";
        return;
    }

    // Antisimon plays
    $antiQuota = gcd($antisimon, $stones);

    if ($antiQuota <= $stones) {
        $stones -= $antiQuota;
    } else {
        echo "0\n";
        return;
    }
}
?>
